package dev.hybridmail;

import static dev.hybridmail.OpenPgp.*;
import java.nio.ByteBuffer;
import java.nio.charset.*;
import java.util.*;

/** Authenticated, reconstructible certificate template for PQMCP002 only.
 * This is deliberately NOT a general certificate repair or signature oracle.
 * We accept the complete, self-issued Level 5 shape generated by PQ Mail and
 * refuse extra keys, revocations, third-party signatures and unknown metadata.
 * Only signature values, digest prefixes and per-signature salts are omitted.
 * Reconstruction uses fresh salts as recommended by RFC 9580 Section 13.2.
 */
final class UltraCertificate {
    private static final int SIGNATURE=114+4627;
    private final byte[] encoded,primary,signing,encryption;
    private final List<Packet> packets;
    private final Map<Integer,Sig> signatures;

    private UltraCertificate(byte[] encoded,boolean zero)throws Exception{
        check(encoded.length>0&&encoded.length<=Level5Companion.MAX,"Ultra certificate size exceeds limit");
        this.packets=strictPackets(encoded);this.signatures=new LinkedHashMap<>();
        check(packets.size()>=8&&packets.size()<=16,"Unsupported ultra certificate packet count");
        primary=packet(0,6);check(primary.length>5&&(primary[5]&255)==31,"Ultra primary must be ML-DSA-87 + Ed448");parseKey(primary,true);
        signatures.put(1,new Sig(packet(1,2),keyHash(primary),31,primary,primary,"direct",zero));
        int index=2,count=0;var emails=new HashSet<String>();
        // Preserve the complete UID packet. Reject duplicate emails rather than
        // silently coalescing their certifications into a different identity.
        while(index<packets.size()&&packets.get(index).tag()==13){
            byte[] uid=packet(index,13);check(uid.length>0&&uid.length<=1024,"Invalid ultra user ID size");
            String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(uid)).toString();
            int left=text.lastIndexOf('<');String email=left>=0&&text.endsWith(">")?text.substring(left+1,text.length()-1):text;
            validateEmail(email);check(emails.add(email.toLowerCase(Locale.ROOT)),"Duplicate ultra email address");
            signatures.put(index+1,new Sig(packet(index+1,2),cat(keyHash(primary),b(0xb4),n(uid.length,4),uid),19,primary,primary,"uid",zero));index+=2;count++;
        }
        check(count>=1&&count<=5&&packets.size()==index+4,"Expected 1–5 UIDs and exactly two ultra subkeys");
        signing=packet(index,14);check(signing.length>5&&(signing[5]&255)==31,"Ultra signing subkey must be ML-DSA-87 + Ed448");parseKey(signing,true);
        check(!Arrays.equals(primary,signing),"Certification and signing keys must be separate");
        Keys certificationKeys=parseKey(primary,true),signingKeys=parseKey(signing,true);
        check(!Arrays.equals(certificationKeys.ec().getEncoded(),signingKeys.ec().getEncoded())&&!Arrays.equals(certificationKeys.pq().getEncoded(),signingKeys.pq().getEncoded()),"Ultra certification and signing components must be separate keys");
        signatures.put(index+1,new Sig(packet(index+1,2),cat(keyHash(primary),keyHash(signing)),24,primary,signing,"sign",zero));
        encryption=packet(index+2,14);check(encryption.length>5&&(encryption[5]&255)==36,"Ultra encryption subkey must be ML-KEM-1024 + X448");parseKey(encryption,false);
        signatures.put(index+3,new Sig(packet(index+3,2),cat(keyHash(primary),keyHash(encryption)),24,primary,encryption,"kem",zero));
        // Packet headers are normalized, but each packet body, subpacket order,
        // salt-size field and key creation timestamp remain byte-for-byte exact.
        var out=new Buffer();for(int i=0;i<packets.size();i++)out.put(frame(packets.get(i).tag(),signatures.containsKey(i)?signatures.get(i).normalized():packets.get(i).body()));
        this.encoded=out.toByteArray();if(zero)check(Arrays.equals(this.encoded,encoded),"Noncanonical ultra template framing or nonzero signature data");
    }
    private static List<Packet> strictPackets(byte[] encoded)throws Exception{
        // The normal mail parser deliberately ignores marker/padding packets.
        // Conversion cannot do that: extra packets must keep full storage.
        var result=new ArrayList<Packet>();var r=new Reader(encoded);
        while(r.left()>0){int header=r.one();check((header&0xc0)==0xc0,"Ultra certificates require new-format packet headers");int tag=header&63;check(Set.of(6,2,13,14).contains(tag),"Extra certificate packet requires full storage");int length=r.length();check(length>0&&length<=r.left(),"Invalid ultra packet length");result.add(new Packet(tag,r.take(length)));check(result.size()<=16,"Too many ultra certificate packets");}
        return result;
    }
    private byte[] packet(int index,int tag)throws Exception{check(index<packets.size()&&packets.get(index).tag()==tag,"Unsupported certificate structure; keep full certificate storage");return packets.get(index).body();}
    static UltraCertificate parse(byte[] template)throws Exception{return new UltraCertificate(template,true);}
    static byte[] template(PublicIdentity certificate)throws Exception{
        // Validate a fresh copy, not just a previously constructed cache object.
        // The strict pass below also verifies every embedded cross-signature.
        new PublicIdentity(certificate.encoded);return new UltraCertificate(certificate.encoded,false).encoded();
    }
    static void validateCached(byte[] template,PublicIdentity cached)throws Exception{
        parse(template);check(cached!=null&&Arrays.equals(template,template(cached)),"Cached certificate does not match authenticated ultra template");
    }
    byte[] encoded(){return encoded.clone();}
    byte[] primary(){return primary.clone();}
    byte[] signingBody(){return signing.clone();}
    byte[] encryptionBody(){return encryption.clone();}
    Keys certificationKeys()throws Exception{return parseKey(primary,true);}
    Keys signingKeys()throws Exception{return parseKey(signing,true);}
    Keys encryptionKeys()throws Exception{return parseKey(encryption,false);}

    PublicIdentity reconstruct(Signer certification,Signer signing)throws Exception{
        // Revalidate immediately before any private operation: expiration may
        // have elapsed since a template was inspected or a dialog was opened.
        UltraCertificate current=parse(encoded);var out=new Buffer();
        for(int i=0;i<current.packets.size();i++){
            Packet p=current.packets.get(i);Sig signature=current.signatures.get(i);
            out.put(frame(p.tag(),signature==null?p.body():signature.finish(certification,signing)));
        }
        var own=new PublicIdentity(out.toByteArray());validateCached(encoded,own);return own;
    }

    /** A signature plan contains fully checked public digest inputs only.
     * Its signer and signed data come from the structural parser, never from
     * untrusted issuer claims or caller-selected arbitrary message bytes.
     */
    private static final class Sig {
        final byte[] body,data,issuer,salt;final int headerEnd,prefixAt,saltAt,signatureAt;final Sig cross;final int crossAt;
        Sig(byte[] body,byte[] data,int type,byte[] issuer,byte[] subject,String role,boolean zero)throws Exception{
            this.body=body.clone();this.data=data;this.issuer=issuer;
            var r=new Reader(body);check(Arrays.equals(r.take(4),b(6,type,31,10)),"Ultra signatures require v6 ML-DSA-87 + Ed448 / SHA-512");
            long hashed=r.number(4);check(hashed<=8192,"Ultra hashed metadata exceeds limit");int metadataStart=r.at;byte[] metadata=r.take((int)hashed);headerEnd=r.at;
            check(r.number(4)==0,"Ultra certificates require empty unhashed metadata");prefixAt=r.at;byte[] prefix=r.take(2);check(r.one()==32,"Ultra SHA-512 salt must be 32 bytes");saltAt=r.at;salt=r.take(32);signatureAt=r.at;byte[] value=r.take(r.left());check(value.length==SIGNATURE,"Invalid ultra composite signature size");
            var allowed=new HashSet<>(Set.of(2,3,33));
            if(role.equals("direct"))allowed.addAll(Set.of(9,11,21,22,27,30,39));
            if(role.equals("uid"))allowed.addAll(Set.of(11,21,22,30,39));
            if(role.equals("sign")||role.equals("kem"))allowed.addAll(Set.of(9,27));
            if(role.equals("sign"))allowed.add(32);
            var subs=new LinkedHashMap<Integer,byte[]>();var s=new Reader(metadata);int embeddedOffset=-1;
            while(s.left()>0){int length=s.length();check(length>0&&length<=s.left(),"Invalid ultra signature subpacket");int raw=s.one(),tag=raw&127;check(allowed.contains(tag)&&!subs.containsKey(tag),"Unknown or duplicate ultra signature metadata; keep full storage");check((raw&128)==0||tag!=32,"Critical embedded signature is unsupported");if(tag==32)embeddedOffset=metadataStart+s.at;subs.put(tag,s.take(length-1));}
            check(Arrays.equals(subs.get(33),cat(b(6),fingerprint(issuer))),"Ultra issuer fingerprint mismatch");
            long created=number(subs.get(2),"signature creation time"),keyTime=number(slice(subject,1,5),"key creation time"),issuerTime=number(slice(issuer,1,5),"issuer creation time");
            check(created>=Math.max(keyTime,issuerTime)&&created<=now()+300,"Invalid ultra signature creation time");
            if(subs.containsKey(3)){long duration=number(subs.get(3),"signature expiration");check(duration==0||created+duration>=now(),"Expired ultra signature");}
            if(subs.containsKey(9)){long duration=number(subs.get(9),"key expiration");check(duration==0||keyTime+duration>=now(),"Expired ultra key");}
            int flags=role.equals("direct")?1:role.equals("sign")?2:role.equals("kem")?12:0;
            if(flags!=0)check(Arrays.equals(subs.get(27),b(flags)),"Ultra key flags reject the requested role");
            preferences(subs.get(11),Set.of(7,8,9));preferences(subs.get(21),Set.of(8,9,10,12,14));preferences(subs.get(22),Set.of(0,1,2));
            if(subs.containsKey(30)){byte[] features=subs.get(30);check(features.length==1&&((features[0]&255)&~15)==0,"Unsupported ultra feature flags");}
            if(subs.containsKey(39)){byte[] modes=subs.get(39);check(modes.length>0&&modes.length<=32&&modes.length%2==0,"Invalid ultra AEAD preferences");for(int i=0;i<modes.length;i+=2)check(Set.of(7,8,9).contains(modes[i]&255)&&Set.of(1,2,3).contains(modes[i+1]&255),"Unsupported ultra AEAD preference");}
            // The cross-signature proves possession of the signing subkey and
            // is embedded inside the hashed portion of its primary binding.
            crossAt=embeddedOffset;cross=role.equals("sign")?new Sig(required(subs,32),data,25,subject,issuer,"cross",zero):null;
            if(zero)check(allZero(prefix)&&allZero(salt)&&allZero(value),"Ultra signature, digest-prefix and salt fields must be zero");
            else{byte[] digest=digest(body);check(Arrays.equals(prefix,slice(digest,0,2)),"Ultra signature hash prefix mismatch");verifyDigest(value,digest,parseKey(issuer,true));}
        }
        private static byte[] required(Map<Integer,byte[]> map,int tag)throws Exception{check(map.containsKey(tag),"Missing signing subkey cross-signature");return map.get(tag);}
        private static long number(byte[] value,String name)throws Exception{check(value!=null&&value.length==4,"Invalid ultra "+name);return new Reader(value).number(4);}
        private static boolean allZero(byte[] value){for(byte b:value)if(b!=0)return false;return true;}
        private static void preferences(byte[] value,Set<Integer> allowed)throws Exception{if(value==null)return;check(value.length>0&&value.length<=32,"Invalid ultra preferences");for(byte b:value)check(allowed.contains(b&255),"Unsupported ultra preference");}
        byte[] normalized(){byte[] result=body.clone();if(cross!=null){byte[] child=cross.normalized();System.arraycopy(child,0,result,crossAt,child.length);}Arrays.fill(result,prefixAt,prefixAt+2,(byte)0);Arrays.fill(result,saltAt,result.length,(byte)0);return result;}
        private byte[] digest(byte[] value)throws Exception{return hash("SHA-512",cat(slice(value,saltAt,signatureAt),data,slice(value,0,headerEnd),b(6,255),n(headerEnd,4)));}
        byte[] finish(Signer certification,Signer signing)throws Exception{
            byte[] result=body.clone();
            // Reconstruct the nested proof first, then hash the parent binding
            // with that new proof. Reusing the old parent digest would be wrong.
            if(cross!=null){byte[] child=cross.finish(signing,signing);System.arraycopy(child,0,result,crossAt,child.length);}
            // Reusing stored salts repeats deterministic Ed448 inputs. Fresh
            // salts prevent that without changing key fingerprints or metadata.
            System.arraycopy(random(32),0,result,saltAt,32);
            byte[] digest=digest(result),value=certification.sign(digest);check(value.length==SIGNATURE,"Wrong regenerated signature size");verifyDigest(value,digest,parseKey(issuer,true));
            System.arraycopy(digest,0,result,prefixAt,2);System.arraycopy(value,0,result,signatureAt,value.length);return result;
        }
    }
}
